-- Parte 1/3 — esquema fundacional del nucleo v0.2
BEGIN;
CREATE TABLE IF NOT EXISTS public.unidades_medida(id text PRIMARY KEY,codigo text UNIQUE NOT NULL,nombre text NOT NULL,decimales integer DEFAULT 3 NOT NULL,activo boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS public.proveedores(id text PRIMARY KEY,codigo text UNIQUE NOT NULL,nombre text NOT NULL,activo boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS public.colores(id text PRIMARY KEY,codigo text UNIQUE NOT NULL,nombre text UNIQUE NOT NULL,activo boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS public.ubicaciones(id text PRIMARY KEY,codigo text UNIQUE NOT NULL,nombre text NOT NULL,area_id text NOT NULL,subarea_id text,ubicacion_padre_id text,tipo_ubicacion text NOT NULL,permite_existencia boolean DEFAULT true NOT NULL,activo boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS public.articulo_unidades_operativas(articulo_id text NOT NULL,unidad_operativa_id text NOT NULL,unidad_base_id text NOT NULL,factor_conversion numeric(18,6) NOT NULL,umbral_sugerencia numeric(18,3),es_predeterminada boolean DEFAULT false NOT NULL,activo boolean DEFAULT true NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,PRIMARY KEY(articulo_id,unidad_operativa_id));
CREATE TABLE IF NOT EXISTS public.estructuras_producto(id text PRIMARY KEY,articulo_id text NOT NULL,version text NOT NULL,vigente_desde date NOT NULL,vigente_hasta date,activa boolean DEFAULT true NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,creado_por text);
CREATE TABLE IF NOT EXISTS public.estructura_componentes(id text PRIMARY KEY,estructura_producto_id text NOT NULL,articulo_componente_id text NOT NULL,cantidad_requerida numeric(18,3) NOT NULL,unidad_id text NOT NULL,permite_sustituto boolean DEFAULT false NOT NULL);
CREATE TABLE IF NOT EXISTS public.ordenes_produccion(id text PRIMARY KEY,numero_op text UNIQUE NOT NULL,area_id text NOT NULL,articulo_id text NOT NULL,estructura_producto_id text,cantidad_programada numeric(18,3) NOT NULL,unidad_id text NOT NULL,estado_produccion text NOT NULL,fecha_programada_inicio timestamptz,fecha_compromiso timestamptz,fecha_inicio_real timestamptz,fecha_cierre_real timestamptz,creado_por text NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,codigo_lote text,lote_id text);
CREATE TABLE IF NOT EXISTS public.orden_colores(id text PRIMARY KEY,orden_produccion_id text NOT NULL,color_id text NOT NULL,cantidad_programada numeric(18,3));
CREATE TABLE IF NOT EXISTS public.lotes(id text PRIMARY KEY,codigo_lote text NOT NULL,articulo_id text NOT NULL,tipo_origen text NOT NULL,area_origen_id text,proveedor_id text,orden_produccion_id text UNIQUE,fecha_fabricacion date,fecha_recepcion timestamptz,fecha_caducidad date,estado_calidad text NOT NULL,estado_liberacion text NOT NULL,activo boolean DEFAULT true NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,lote_proveedor text,analisis_calidad_id text);
CREATE TABLE IF NOT EXISTS public.unidades_logisticas(id text PRIMARY KEY,identificador_visible text,tipo_unidad_logistica text NOT NULL,lote_id text,estado_identificacion text NOT NULL,activo boolean DEFAULT true NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.movimientos_inventario(id text PRIMARY KEY,tipo_movimiento text NOT NULL,lote_id text NOT NULL,unidad_logistica_id text,cantidad numeric(18,3) NOT NULL,unidad_id text NOT NULL,ubicacion_origen_id text,estado_origen text,ubicacion_destino_id text,estado_destino text,estado_movimiento text NOT NULL,fecha_efectiva timestamptz DEFAULT now() NOT NULL,confirmado_por text,movimiento_reversado_id text UNIQUE,motivo_ajuste text,creado_en timestamptz DEFAULT now() NOT NULL,creado_por text NOT NULL);
CREATE TABLE IF NOT EXISTS public.movimiento_reversiones(id text PRIMARY KEY,movimiento_original_id text UNIQUE NOT NULL,movimiento_reversion_id text UNIQUE NOT NULL,solicitado_por text NOT NULL,solicitado_en timestamptz DEFAULT now() NOT NULL,autorizado_por text NOT NULL,autorizado_en timestamptz DEFAULT now() NOT NULL,motivo text NOT NULL,estado text DEFAULT 'APLICADA' NOT NULL);
CREATE TABLE IF NOT EXISTS public.reservas_inventario(id text PRIMARY KEY,orden_produccion_id text NOT NULL,lote_id text NOT NULL,ubicacion_id text NOT NULL,unidad_logistica_id text,cantidad numeric(18,3) NOT NULL,unidad_id text NOT NULL,estado_reserva text NOT NULL,reservado_en timestamptz DEFAULT now() NOT NULL,reservado_por text NOT NULL,liberado_en timestamptz,liberado_por text);
CREATE TABLE IF NOT EXISTS public.solicitudes_material(id text PRIMARY KEY,folio_solicitud text UNIQUE NOT NULL,orden_produccion_id text NOT NULL,area_solicitante_id text NOT NULL,estado_solicitud text NOT NULL,solicitado_por text NOT NULL,solicitado_en timestamptz DEFAULT now() NOT NULL,fecha_requerida timestamptz,observaciones text);
CREATE TABLE IF NOT EXISTS public.solicitud_detalles(id text PRIMARY KEY,solicitud_material_id text NOT NULL,articulo_id text NOT NULL,cantidad_solicitada numeric(18,3) NOT NULL,cantidad_cancelada numeric(18,3) DEFAULT 0 NOT NULL,unidad_id text NOT NULL,UNIQUE(solicitud_material_id,articulo_id));
CREATE TABLE IF NOT EXISTS public.surtidos(id text PRIMARY KEY,folio_surtido text UNIQUE NOT NULL,solicitud_material_id text NOT NULL,estado_surtido text NOT NULL,preparado_por text,entregado_por text,recibido_por text,preparado_en timestamptz,entregado_en timestamptz,recibido_en timestamptz,motivo_diferencia text,observaciones text);
CREATE TABLE IF NOT EXISTS public.surtido_detalles(id text PRIMARY KEY,surtido_id text NOT NULL,solicitud_detalle_id text NOT NULL,lote_id text NOT NULL,unidad_logistica_id text,cantidad_entregada numeric(18,3) NOT NULL,cantidad_recibida numeric(18,3),unidad_id text NOT NULL,ubicacion_origen_id text NOT NULL,ubicacion_destino_id text NOT NULL,movimiento_inventario_id text UNIQUE);
CREATE TABLE IF NOT EXISTS public.consumos(id text PRIMARY KEY,folio_consumo text UNIQUE NOT NULL,orden_produccion_id text NOT NULL,estado_consumo text NOT NULL,registrado_por text NOT NULL,registrado_en timestamptz DEFAULT now() NOT NULL,confirmado_por text,confirmado_en timestamptz,observaciones text);
CREATE TABLE IF NOT EXISTS public.consumo_detalles(id text PRIMARY KEY,consumo_id text NOT NULL,lote_id text NOT NULL,unidad_logistica_id text,color_id text,cantidad_consumida numeric(18,3) NOT NULL,unidad_id text NOT NULL,ubicacion_origen_id text NOT NULL,movimiento_inventario_id text UNIQUE);
CREATE TABLE IF NOT EXISTS public.devoluciones(id text PRIMARY KEY,folio_devolucion text UNIQUE NOT NULL,orden_produccion_id text NOT NULL,estado_devolucion text NOT NULL,motivo text NOT NULL,entregado_por text NOT NULL,entregado_en timestamptz,recibido_por text,recibido_en timestamptz,observaciones text,tipo_devolucion text DEFAULT 'ALMACEN' NOT NULL,es_excedente_documental boolean DEFAULT false NOT NULL,autorizado_por text,autorizado_en timestamptz);
CREATE TABLE IF NOT EXISTS public.devolucion_detalles(id text PRIMARY KEY,devolucion_id text NOT NULL,lote_id text NOT NULL,unidad_logistica_id text,cantidad_declarada numeric(18,3) NOT NULL,cantidad_recibida numeric(18,3),unidad_id text NOT NULL,ubicacion_origen_id text NOT NULL,ubicacion_destino_id text NOT NULL,estado_identificacion text NOT NULL,movimiento_inventario_id text UNIQUE,motivo_detalle text,metodo_determinacion text);
CREATE TABLE IF NOT EXISTS public.devolucion_asignaciones(id text PRIMARY KEY,devolucion_detalle_id text NOT NULL,surtido_detalle_id text NOT NULL,cantidad_asignada numeric(18,3) NOT NULL,metodo_asignacion text NOT NULL,asignado_por text,asignado_en timestamptz DEFAULT now() NOT NULL,UNIQUE(devolucion_detalle_id,surtido_detalle_id));
CREATE TABLE IF NOT EXISTS public.reportes_produccion(id text PRIMARY KEY,folio_reporte text,orden_produccion_id text NOT NULL,fecha_inicio timestamptz,fecha_fin timestamptz DEFAULT now() NOT NULL,estado_reporte text DEFAULT 'BORRADOR' NOT NULL,reportado_por text,reportado_en timestamptz DEFAULT now(),confirmado_por text,confirmado_en timestamptz,lote_id text,movimiento_inventario_id text,observaciones text,cantidad_capturada numeric(18,3),unidad_capturada_id text,factor_conversion numeric(18,6),cantidad_base numeric(18,3),unidad_base_id text);
CREATE TABLE IF NOT EXISTS public.dictamenes_calidad_produccion(id text PRIMARY KEY,folio_dictamen text,orden_produccion_id text NOT NULL,lote_id text,cantidad_capturada numeric(18,3),unidad_capturada_id text,factor_conversion numeric(18,6),cantidad_base numeric(18,3),unidad_base_id text,resultado_original text,estado_dictamen text DEFAULT 'BORRADOR',motivo text,inspeccionado_por text,inspeccionado_en timestamptz DEFAULT now(),confirmado_por text,confirmado_en timestamptz,creado_en timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.disposiciones_calidad(id text PRIMARY KEY,folio_disposicion text,dictamen_id text,tipo_disposicion text,cantidad_base numeric(18,3),unidad_base_id text,estado_disposicion text DEFAULT 'PENDIENTE',solicitada_por text,solicitada_en timestamptz DEFAULT now(),autorizada_por text,autorizada_en timestamptz,motivo text,evidencia_referencia text);
CREATE TABLE IF NOT EXISTS public.entregas_produccion(id text PRIMARY KEY,folio_entrega text,ubicacion_origen_id text,ubicacion_destino_id text,cantidad_entregada numeric(18,3),unidad_id text,estado_entrega text DEFAULT 'BORRADOR',preparado_por text,preparado_en timestamptz DEFAULT now(),recibido_por text,recibido_en timestamptz,movimiento_inventario_id text,observaciones text,orden_produccion_id text NOT NULL,lote_id text);
CREATE TABLE IF NOT EXISTS public.analisis_calidad_materiales(id text PRIMARY KEY,numero_analisis text UNIQUE NOT NULL,tipo_analisis text NOT NULL,folio_ft_al_01 text,articulo_id text NOT NULL,estado_dictamen text DEFAULT 'PENDIENTE' NOT NULL,fecha_dictamen date,inspeccionado_por text,confirmado_por text,observaciones text,creado_por text NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,confirmado_en timestamptz);
CREATE TABLE IF NOT EXISTS public.dictamenes_calidad_materiales(id text PRIMARY KEY,analisis_id text NOT NULL,resultado text NOT NULL,fecha_dictamen date DEFAULT CURRENT_DATE NOT NULL,inspeccionado_por text NOT NULL,confirmado_por text NOT NULL,observaciones text,estado text DEFAULT 'APLICADO',analisis_resultante_id text NOT NULL,creado_en timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.recepciones_materiales(id text PRIMARY KEY,articulo_id text NOT NULL,tipo_analisis text NOT NULL,numero_analisis text DEFAULT '' NOT NULL,folio_ft_al_01 text,codigo_lote text NOT NULL,lote_proveedor text,proveedor_id text,area_origen_id text,cantidad_capturada numeric(18,3) NOT NULL,unidad_capturada_id text NOT NULL,cantidad_base numeric(18,3) DEFAULT 0 NOT NULL,unidad_base_id text DEFAULT '' NOT NULL,ubicacion_cuarentena_id text NOT NULL,fecha_fabricacion date,fecha_recepcion timestamptz DEFAULT now() NOT NULL,fecha_caducidad date,recibido_por text NOT NULL,observaciones text,analisis_calidad_id text DEFAULT '' NOT NULL,lote_id text UNIQUE DEFAULT '' NOT NULL,movimiento_inventario_id text UNIQUE DEFAULT '' NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL,analisis_existente_id text,estado text DEFAULT 'ACTIVA' NOT NULL,reversion_recepcion_id text,revertida_en timestamptz,CONSTRAINT recepciones_materiales_reversion_consistencia_ck CHECK((estado='ACTIVA' AND reversion_recepcion_id IS NULL AND revertida_en IS NULL) OR (estado='REVERTIDA' AND reversion_recepcion_id IS NOT NULL AND revertida_en IS NOT NULL)));
CREATE TABLE IF NOT EXISTS public.reversiones_recepciones_materiales(id text PRIMARY KEY,recepcion_id text UNIQUE NOT NULL,solicitado_por text NOT NULL,autorizado_por text NOT NULL,motivo text NOT NULL,movimiento_reversion_id text DEFAULT '' NOT NULL,evento_reversion_id text DEFAULT '' NOT NULL,estado text DEFAULT 'APLICADA' NOT NULL,creado_en timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.lote_eventos_calidad(id text PRIMARY KEY,lote_id text NOT NULL,estado_calidad_anterior text NOT NULL,estado_calidad_nuevo text NOT NULL,estado_liberacion_anterior text NOT NULL,estado_liberacion_nuevo text NOT NULL,tipo_evento text NOT NULL,motivo text NOT NULL,referencia_concesion text,registrado_por text NOT NULL,registrado_en timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS public.versiones_nucleo(version text PRIMARY KEY,descripcion text NOT NULL,rama_id text NOT NULL,instalada_en timestamptz DEFAULT now() NOT NULL,estado text NOT NULL,observaciones text);
COMMIT;
